let vocations=JSON.parse(JSON.stringify(ORIGINAL_VOCATIONS)), tracks=JSON.parse(JSON.stringify(ORIGINAL_TRACKS));
const blank=()=>({name:"",age:"",birthplace:"",serviceYears:0,stage:1,attributes:Object.fromEntries(ATTRS.map(a=>[a,1])),vital:20,lucidity:20,essence:10,collapse:0,state:"",defense:0,baseDefense:10,vocation:null,archetype:"",track:null,extraSkills:[],customTalents:[],activeTalents:[],rituals:"",knownRituals:[],ritualHistory:[],chronicle:"",items:"",connections:"",notes:"",skillOverrides:{},inventory:{weapons:[],gear:[],backpack:[],ammo:{}},statuses:[],traumas:[],collapseCount:0,combatSurprised:false});
let data=blank(), pendingVoc=null,pendingTrack=null,pendingTalent=null;
const $=id=>document.getElementById(id), clone=x=>JSON.parse(JSON.stringify(x));
const bc=("BroadcastChannel" in window)?new BroadcastChannel("tulpa-rpg-sync"):null;
function toast(msg){$("toast").textContent=msg;$("toast").classList.add("show");setTimeout(()=>$("toast").classList.remove("show"),2200)}
function persistOnly(){localStorage.setItem("tulpa-rpg-character",JSON.stringify(data));localStorage.setItem("tulpa-rpg-vocations",JSON.stringify(vocations));localStorage.setItem("tulpa-rpg-tracks",JSON.stringify(tracks));$("saveStatus").textContent="Salvo · "+new Date().toLocaleTimeString("pt-BR",{hour:"2-digit",minute:"2-digit"});if(bc)bc.postMessage({data,vocations,tracks})}
function save(){persistOnly();render()}
function load(){try{const d=JSON.parse(localStorage.getItem("tulpa-rpg-character"));if(d)data={...blank(),...d};const v=JSON.parse(localStorage.getItem("tulpa-rpg-vocations"));if(v)vocations=v;const t=JSON.parse(localStorage.getItem("tulpa-rpg-tracks"));if(t)tracks=t}catch(e){}}
if(bc)bc.onmessage=e=>{if(e.data?.data){data={...blank(),...e.data.data};vocations=e.data.vocations||vocations;tracks=e.data.tracks||tracks;render();toast("Ficha atualizada em outra aba")}};
function stageStats(){return STAGES[data.stage]||STAGES[1]}
function attrMax(){return data.stage>=2?4:3}
function attrPointsLeft(){return 7+stageStats().attr-(Object.values(data.attributes).reduce((a,b)=>a+(Number(b)||1),0)-8)}
function vocation(){return vocations.find(v=>v.name===data.vocation)||null}
function track(){return tracks.find(t=>t.name===data.track&&t.archetype===data.archetype)||null}
function vocBonus(skill){const v=vocation();if(!v||!v.skills.includes(skill))return 0;const y=Number(data.serviceYears)||0;return y>=40?15:y>=10?10:5}
function activeSkillBonus(skill){let bonus=0;for(const id of data.activeTalents||[]){const [src,index]=id.split(":");let item;if(src==="voc")item=vocation()?.talents[+index];else{const eligible=track()?.stages.filter(s=>s.stage<=data.stage)||[];item=eligible[+index]}if(!item)continue;const re=new RegExp("\\+(\\d+)\\s+(?:temporários?\\s+)?em\\s+"+skill.replace(/[.*+?^${}()|[\\]\\\\]/g,"\\\\$&"),"i");const m=item.desc.match(re);if(m)bonus+=Number(m[1])}return bonus}
function skillBonus(skill){const extra=(data.extraSkills||[]).filter(x=>x===skill).length*5;return (data.skillOverrides?.[skill]||0)+extra+vocBonus(skill)+activeSkillBonus(skill)}
function currentAttr(skill){return Number(data.attributes[SKILL_ATTR[skill]]||1)}
function stageName(n){return ["","Iniciante","Aprendiz","Arquétipo","Caminhante","Veterano","Experiente","Intelectual","Exímio","Lenda Viva","Singularidade"][n]}
function setStat(id,key,max){const cur=Number(data[key]??max);const value=Math.max(0,Math.min(max,cur));return `<div class="stat"><div class="name">${id}</div><div class="value">${value}<span class="max"> / ${max}</span></div><input aria-label="${id} atual" type="range" min="0" max="${max}" value="${value}" data-stat="${key}" style="width:100%;accent-color:#80b8af"><div class="bar"><span style="width:${max?value/max*100:0}%"></span></div></div>`}
function renderStats(){const s=stageStats();$("stats").innerHTML=setStat("VITAL","vital",s.vt)+setStat("LUCIDEZ","lucidity",s.luc)+setStat("ESSÊNCIA","essence",s.es);document.querySelectorAll("[data-stat]").forEach(el=>{el.oninput=()=>{data[el.dataset.stat]=+el.value;persistOnly()};el.onchange=()=>renderStats()});$("essenceNow").textContent=`ES ${data.essence} / ${s.es}`}
function renderStages(){$("stageTag").textContent=`ESTÁGIO ${data.stage} · ${stageName(data.stage).toUpperCase()}`;$("stageRead").value=data.stage;$("pointsLabel").textContent=`${attrPointsLeft()} pontos de atributo disponíveis`;$("stageList").innerHTML=Array.from({length:10},(_,i)=>i+1).map(n=>`<button class="stage ${n===data.stage?"selected":""}" data-stage="${n}"><b>${String(n).padStart(2,"0")}</b><small>${stageName(n)}</small></button>`).join("");document.querySelectorAll("[data-stage]").forEach(b=>b.onclick=()=>{const n=+b.dataset.stage;const up=n>data.stage,old=E.maxStats(data);data.stage=n;const next=E.maxStats(data);if(up){data.vital+=next.vt-old.vt;data.lucidity+=next.luc-old.luc;data.essence+=next.es-old.es}else{data.vital=Math.min(data.vital,next.vt);data.lucidity=Math.min(data.lucidity,next.luc);data.essence=Math.min(data.essence,next.es)}save()})}
function renderAttributes(){$("attributes").innerHTML=ATTRS.map(a=>`<div class="attr-card"><div class="attr-top"><strong>${a.toUpperCase()}</strong><span class="tag">${Object.entries(SKILL_ATTR).filter(([s,x])=>x===a).length} perícias</span></div><div class="counter"><button data-attr="${a}" data-dir="-1">−</button><b>${data.attributes[a]||1}</b><button data-attr="${a}" data-dir="1">+</button></div></div>`).join("");$("attrPoints").textContent=`${attrPointsLeft()} pontos livres`;document.querySelectorAll("[data-attr]").forEach(b=>b.onclick=()=>{const a=b.dataset.attr,dir=+b.dataset.dir,now=data.attributes[a]||1,max0=E.maxStats(data);if(dir>0&&attrPointsLeft()>0&&now<attrMax())data.attributes[a]=now+1;if(dir<0&&now>1)data.attributes[a]=now-1;E.syncMax(data,max0);save()});$("archRead").value=data.archetype}
function pendingTalentBonus(skill){return (data.activeEffects||[]).filter(e=>e.type==='once'&&(e.skill===skill||(Array.isArray(e.skills)&&e.skills.includes(skill)))).reduce((n,e)=>n+(Number(e.value)||0),0)}
function renderSkills(){const q=($("skillSearch").value||"").toLowerCase();$("skillGrid").innerHTML=BASE_SKILLS.filter(s=>s.toLowerCase().includes(q)).map(s=>`<div class="skill"><div class="skill-info"><div class="skill-name">${s}</div><div class="skill-attr">${SKILL_ATTR[s]} · ${currentAttr(s)}d20 · vocação +${vocBonus(s)}</div></div><div class="skill-right"><span class="skill-val">+${skillBonus(s)+pendingTalentBonus(s)}</span><button class="roll" data-roll="${s}">D20</button></div></div>`).join("");document.querySelectorAll("[data-roll]").forEach(b=>b.onclick=()=>rollSkill(b.dataset.roll));$("extraSkillsLabel").textContent=`${data.extraSkills.length} / ${stageStats().extra} escolhas extras`;$("skillSlots").textContent=`${Math.max(0,stageStats().extra-data.extraSkills.length)} escolhas restantes`;$("addSkillSelect").innerHTML=BASE_SKILLS.map(s=>`<option>${s}</option>`).join("");$("extraSkillList").innerHTML=data.extraSkills.map((s,i)=>`<span class="pill">${s} +5 <button data-remove-extra="${i}" style="background:none;border:0;color:#e6a3a6">×</button></span>`).join("")||'<span class="sub">Nenhum bônus extra aplicado.</span>';document.querySelectorAll("[data-remove-extra]").forEach(b=>b.onclick=()=>{data.extraSkills.splice(+b.dataset.removeExtra,1);save()})}
function rollSkill(skill){const n=Math.max(1,currentAttr(skill)),rolls=Array.from({length:n},()=>1+Math.floor(Math.random()*20)),best=Math.max(...rolls),bonus=skillBonus(skill),total=best+bonus;openModal("ROLAGEM DE APTIDÃO",`${skill} · ${n}d20 + ${bonus}`,`<div class="roll-result"><div class="sub">Dados lançados · maior resultado mantido</div><div class="dice">${rolls.map(x=>`<span class="die ${x===best?"best":"discard"}">${x}</span>`).join("")}</div><div class="bigresult">${total}</div><div class="sub">Maior dado ${best} + bônus da perícia ${bonus} = ${total}</div></div>`, "Fechar",()=>closeModal())}
function renderVocations(){const sel=$("vocSelect"),keep=sel.value;sel.innerHTML=vocations.slice().sort((a,b)=>a.name.localeCompare(b.name,"pt-BR")).map(v=>`<option value="${escapeAttr(v.name)}">${escapeHtml(v.name)}</option>`).join("");if(keep&&vocations.some(v=>v.name===keep))sel.value=keep;else if(data.vocation&&vocations.some(v=>v.name===data.vocation))sel.value=data.vocation;$("vocCount").textContent=`${vocations.length} vocações`; $("currentVoc").textContent=data.vocation?`Atual: ${data.vocation}`:"Nenhuma vocação confirmada";if(data.vocation){const v=vocation();$("overviewVoc").innerHTML=v?`<b>${escapeHtml(v.name)}</b><p>${escapeHtml(v.desc)}</p><span class="tag">${v.skills.join(" · ")}</span>`:"Vocação removida do catálogo."}else $("overviewVoc").textContent="Nenhuma vocação selecionada."}
function previewVoc(){const v=vocations.find(x=>x.name===$("vocSelect").value);pendingVoc=v||null;$("confirmVoc").disabled=!v;if(!v){$("vocPreview").innerHTML='<div class="empty">Selecione uma vocação.</div>';return}$("vocPreview").innerHTML=`<h4>${escapeHtml(v.name)}</h4><p>${escapeHtml(v.desc)}</p><div class="meta">${v.skills.map(s=>`<span class="tag">${s} +V</span>`).join("")}</div><h3 style="margin-top:14px">Talentos da vocação</h3>${v.talents.map(t=>`<p><b>${escapeHtml(t.name)}</b> · ${t.cost} ES<br>${escapeHtml(t.desc)}</p>`).join("")}`}
function renderTracks(){const arch=$("archSelect");arch.value=data.archetype||"";const list=tracks.filter(t=>t.archetype===arch.value).sort((a,b)=>a.name.localeCompare(b.name,"pt-BR"));$("trackSelect").innerHTML=list.map(t=>`<option value="${escapeAttr(t.name)}">${escapeHtml(t.name)}</option>`).join("");if(data.track&&list.some(t=>t.name===data.track))$("trackSelect").value=data.track;$("trackCount").textContent=`${tracks.length} trilhas`;if(data.track){$("overviewTrack").innerHTML=`<b>${escapeHtml(data.track)}</b><p>${escapeHtml(data.archetype)}</p>`}else $("overviewTrack").textContent="Nenhuma trilha selecionada."; $("currentTrack").textContent=data.track?`Atual: ${data.track}`:"Nenhuma trilha confirmada.";previewTrack()}
function previewTrack(){const t=tracks.find(x=>x.archetype===$("archSelect").value&&x.name===$("trackSelect").value);pendingTrack=t||null;$("confirmTrack").disabled=!t||data.stage<3;$("trackPreview").innerHTML=t?`<h4>${escapeHtml(t.name)}</h4><p>${escapeHtml(t.desc)}</p><div class="meta"><span class="tag">${t.archetype}</span><span class="tag">Habilidades nos estágios 3, 5, 8 e 10</span></div>${t.stages.map(s=>`<p style="margin-top:10px"><b>Estágio ${s.stage} · ${escapeHtml(s.name)}</b> — ${escapeHtml(s.desc)}</p>`).join("")}`:'<div class="empty">Escolha um arquétipo e uma trilha.</div>';renderTrackStages()}
function renderTrackStages(){const t=track();if(!t){$("trackStages").innerHTML='<div class="empty">Confirme uma trilha para visualizar as habilidades.</div>';return}$("trackStages").innerHTML=t.stages.map(s=>`<div class="choice"><div class="inline"><span class="tag">ESTÁGIO ${s.stage}</span><span class="pill">${s.cost} ES</span></div><h4 style="margin-top:8px">${escapeHtml(s.name)}</h4><p>${escapeHtml(s.desc)}</p><div class="meta">${s.stage<=data.stage?'<span class="tag">Liberada</span>':'<span class="pill">Bloqueada até estágio '+s.stage+'</span>'}</div></div>`).join("")}
function renderTalents(){const v=vocation(),t=track();const draw=(talents,source)=>talents.map((x,i)=>{const id=`${source}:${i}`,active=data.activeTalents.includes(id);return `<div class="talent ${active?"active":""}"><div class="grow"><h4>${escapeHtml(x.name)} <span class="pill">${x.cost} ES</span></h4><p>${escapeHtml(x.desc)}</p><div class="meta">${active?'<span class="tag">Ativo nesta ficha</span>':""}</div></div><button class="btn small ${active?"":"primary"}" data-activate="${id}" ${active?"disabled":""}>${active?"Ativo":"Ativar"}</button></div>`}).join("");$("vocationTalents").innerHTML=v?draw(v.talents,"voc"):'<div class="empty">Selecione uma vocação.</div>';$("trackTalents").innerHTML=t?draw(t.stages.filter(s=>s.stage<=data.stage).map(s=>({name:s.name,cost:s.cost,desc:s.desc,stage:s.stage})),"track"):'<div class="empty">Selecione uma trilha.</div>';document.querySelectorAll("[data-activate]").forEach(b=>b.onclick=()=>activateTalent(b.dataset.activate));$("customTalents").innerHTML=data.customTalents.map((x,i)=>`<div class="choice"><div class="inline"><h4>${escapeHtml(x)}</h4><button class="btn small danger right" data-del-custom="${i}">Excluir</button></div></div>`).join("")||'<div class="empty">Nenhuma anotação adicionada.</div>';document.querySelectorAll("[data-del-custom]").forEach(b=>b.onclick=()=>{data.customTalents.splice(+b.dataset.delCustom,1);save()})}
function activateTalent(id){const [src,index]=id.split(":");let item;if(src==="voc")item=vocation()?.talents[+index];else{const eligible=track()?.stages.filter(s=>s.stage<=data.stage)||[];item=eligible[+index]}if(!item)return;if(data.essence<item.cost){toast("Essência insuficiente.");return}openModal("CONFIRMAR ATIVAÇÃO",item.name,`<p>${escapeHtml(item.desc)}</p><div class="notice">Esta ativação consumirá <b>${item.cost} ES</b>. Essência disponível: ${data.essence} ES.</div>`,"Ativar e descontar",()=>{data.essence-=item.cost;data.activeTalents.push(id);closeModal();save();toast("Talento ativado.")})}
function openModal(eyebrow,title,body,confirmText,action){$("modalEyebrow").textContent=eyebrow;$("modalTitle").textContent=title;$("modalBody").innerHTML=body;$("modalConfirm").textContent=confirmText;$("modalConfirm").onclick=action;$("modalWrap").classList.add("open")}
function closeModal(){$("modalWrap").classList.remove("open")}
function escapeHtml(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}function escapeAttr(s){return escapeHtml(s).replace(/"/g,"&quot;")}
function normalizeAgeAndService(target=data){const d=target;if(d.age!==""&&d.age!==null&&d.age!==undefined){const age=Math.min(120,Math.max(1,Math.trunc(Number(d.age)||1)));d.age=age}const max=d.age===""?120:Number(d.age)||120;d.serviceYears=Math.min(max,Math.max(0,Math.trunc(Number(d.serviceYears)||0)))}
function render(){normalizeAgeAndService();renderStats();renderStages();renderAttributes();renderSkills();renderVocations();renderTracks();renderTalents();$("charName").value=data.name;$("age").value=data.age;$("birthplace").value=data.birthplace;$("serviceYears").value=data.serviceYears;$("serviceYears").max=data.age===""?120:data.age;$("state").value=data.state;$("collapse").value=data.collapse;$("defense").value=data.defense;$("baseDefense").value=data.baseDefense;$("rituals").value=data.rituals;$("chronicle").value=data.chronicle;$("items").value=data.items;$("connections").value=data.connections;$("notes").value=data.notes}
function bindInput(id,key,type="value"){const el=$(id);if(id==="age"||id==="serviceYears"){const update=()=>{const raw=String(el.value).trim(),value=Number(raw);if(id==="age"){data.age=raw===""?"":Number.isFinite(value)?Math.min(120,Math.max(1,Math.trunc(value))):"";el.value=data.age;const svc=$("serviceYears"),max=data.age===""?120:data.age;svc.max=max;if(Number(data.serviceYears)>max){data.serviceYears=max;svc.value=max}}else{const max=data.age===""?120:Number(data.age)||120;data.serviceYears=raw===""?0:Number.isFinite(value)?Math.min(max,Math.max(0,Math.trunc(value))):0;el.value=data.serviceYears;el.max=max}persistOnly()};el.addEventListener("input",update);el.addEventListener("change",update);return}el.addEventListener("input",()=>{data[key]=type==="number"?(Number(el.value)||0):el.value;persistOnly()})}
function addVoc(){const name=$("newVocName").value.trim(),desc=$("newVocDesc").value.trim(),sk=$("newVocSkills").value.split(",").map(x=>x.trim()).filter(Boolean);if(!name||sk.length!==3){toast("Informe nome e exatamente três perícias.");return}const parse=s=>{const p=s.split("|").map(x=>x.trim());return{name:p[0]||"Talento",cost:Number(p[1])||0,desc:p[2]||"Talento personalizado."}};vocations.push({name,desc,skills:sk,talents:[parse($("newVocT1").value),parse($("newVocT2").value)]});save();toast("Vocação adicionada.");["newVocName","newVocDesc","newVocSkills","newVocT1","newVocT2"].forEach(x=>$(x).value="")}
function addTrack(){const name=$("newTrackName").value.trim(),arch=$("newTrackArch").value,desc=$("newTrackDesc").value.trim();if(!name){toast("Informe o nome da trilha.");return}const parse=(s,stage)=>{const p=s.split("|").map(x=>x.trim());return{stage,name:p[0]||`Habilidade ${stage}`,cost:Number(p[1])||0,desc:p[2]||"Habilidade personalizada."}};tracks.push({archetype:arch,name,desc,stages:[parse($("newTrack3").value,3),parse($("newTrack5").value,5),parse($("newTrack8").value,8),parse($("newTrack10").value,10)]});save();toast("Trilha adicionada.");["newTrackName","newTrackDesc","newTrack3","newTrack5","newTrack8","newTrack10"].forEach(x=>$(x).value="")}
function editSelected(which){const item=which==="voc"?vocations.find(x=>x.name===$("vocSelect").value):tracks.find(x=>x.name===$("trackSelect").value&&x.archetype===$("archSelect").value);if(!item){toast("Selecione um item primeiro.");return}openModal("EDITOR DO MESTRE",`Editar ${item.name}`,`<div class="field"><label>Nome</label><input id="editName" value="${escapeAttr(item.name)}"></div><div class="field"><label>Descrição</label><textarea id="editDesc">${escapeHtml(item.desc)}</textarea></div>${which==="voc"?`<div class="field"><label>Perícias (separadas por vírgula)</label><input id="editSkills" value="${escapeAttr(item.skills.join(", "))}"></div><div class="field"><label>Talento 1: nome | custo | descrição</label><input id="editT1" value="${escapeAttr(item.talents[0].name+" | "+item.talents[0].cost+" | "+item.talents[0].desc)}"></div><div class="field"><label>Talento 2: nome | custo | descrição</label><input id="editT2" value="${escapeAttr(item.talents[1].name+" | "+item.talents[1].cost+" | "+item.talents[1].desc)}"></div>`:`<div class="field"><label>Arquétipo</label><select id="editArch"><option ${item.archetype==="Lutador"?"selected":""}>Lutador</option><option ${item.archetype==="Gênio"?"selected":""}>Gênio</option><option ${item.archetype==="Ritualista"?"selected":""}>Ritualista</option></select></div>${[3,5,8,10].map((st,i)=>`<div class="field"><label>Estágio ${st}: nome | custo | descrição</label><input id="editS${st}" value="${escapeAttr(item.stages[i].name+" | "+item.stages[i].cost+" | "+item.stages[i].desc)}"></div>`).join("")}`}<button class="btn danger small" id="deleteItem" style="margin-top:10px">Excluir este item</button>`,`Salvar alterações`,()=>{const old=item.name;item.name=$("editName").value.trim()||old;item.desc=$("editDesc").value;if(which==="voc"){item.skills=$("editSkills").value.split(",").map(x=>x.trim()).filter(Boolean);item.talents=[1,2].map((n)=>{const p=$("editT"+n).value.split("|").map(x=>x.trim());return{name:p[0],cost:Number(p[1])||0,desc:p[2]||""}});if(data.vocation===old)data.vocation=item.name}else{item.archetype=$("editArch").value;item.stages=[3,5,8,10].map(st=>{const p=$("editS"+st).value.split("|").map(x=>x.trim());return{stage:st,name:p[0],cost:Number(p[1])||0,desc:p[2]||""}});if(data.track===old)data.track=item.name}closeModal();save();toast("Alterações salvas.")});setTimeout(()=>{const del=$("deleteItem");if(del)del.onclick=()=>{if(!confirm("Excluir este item do catálogo?"))return;if(which==="voc"){vocations=vocations.filter(x=>x!==item);if(data.vocation===item.name)data.vocation=null}else{tracks=tracks.filter(x=>x!==item);if(data.track===item.name)data.track=null}closeModal();save() }},0)}
document.querySelectorAll(".navbtn").forEach(b=>b.onclick=()=>{document.querySelectorAll(".navbtn").forEach(x=>x.classList.toggle("active",x===b));document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x.id==="tab-"+b.dataset.tab))});
