$("skillSearch").oninput=renderSkills;$("vocSearch").oninput=()=>{const q=$("vocSearch").value.toLowerCase();const sel=$("vocSelect"),old=sel.value;sel.innerHTML=vocations.filter(v=>v.name.toLowerCase().includes(q)).sort((a,b)=>a.name.localeCompare(b.name,"pt-BR")).map(v=>`<option>${escapeHtml(v.name)}</option>`).join("");if([...sel.options].some(o=>o.value===old))sel.value=old;previewVoc()};
$("vocSelect").onchange=previewVoc;$("confirmVoc").onclick=()=>{if(!pendingVoc)return;openModal("CONFIRMAR VOCAÇÃO",pendingVoc.name,`<p>${escapeHtml(pendingVoc.desc)}</p><div class="notice">Você receberá +V nas perícias: <b>${pendingVoc.skills.join(", ")}</b>. O valor de +V depende dos anos de serviço informados.</div><p>Esta escolha substituirá a vocação atual.</p>`,"Confirmar escolha",()=>{data.vocation=pendingVoc.name;data.activeTalents=data.activeTalents.filter(x=>!x.startsWith("voc:"));closeModal();save();toast("Vocação confirmada.")})};$("cancelVoc").onclick=()=>{$("vocSelect").value="";pendingVoc=null;$("confirmVoc").disabled=true;$("vocPreview").innerHTML='<div class="empty">Seleção cancelada.</div>'};
$("archSelect").onchange=()=>{data.archetype=$("archSelect").value;data.track=null;renderTracks()};$("trackSelect").onchange=previewTrack;$("confirmTrack").onclick=()=>{if(!pendingTrack||data.stage<3)return;openModal("CONFIRMAR TRILHA",pendingTrack.name,`<p>${escapeHtml(pendingTrack.desc)}</p><div class="notice">Arquétipo: <b>${pendingTrack.archetype}</b>. As habilidades serão liberadas nos estágios 3, 5, 8 e 10. Habilidades ainda não liberadas permanecerão bloqueadas.</div>`,"Confirmar escolha",()=>{data.archetype=pendingTrack.archetype;data.track=pendingTrack.name;data.activeTalents=data.activeTalents.filter(x=>!x.startsWith("track:"));closeModal();save();toast("Trilha confirmada.")})};$("cancelTrack").onclick=()=>{$("trackSelect").value="";pendingTrack=null;$("confirmTrack").disabled=true;$("trackPreview").innerHTML='<div class="empty">Seleção cancelada.</div>'};
$("addSkillBonus").onclick=()=>{if(data.extraSkills.length>=stageStats().extra){toast("Você já usou todas as escolhas extras.");return}if(data.extraSkills.includes($("addSkillSelect").value)){toast("Essa perícia já recebeu um bônus extra.");return}data.extraSkills.push($("addSkillSelect").value);save()};$("removeSkillBonus").onclick=()=>{const s=$("addSkillSelect").value,i=data.extraSkills.lastIndexOf(s);if(i<0){toast("Essa perícia não tem bônus extra.");return}data.extraSkills.splice(i,1);save()};
$("saveCustomTalent").onclick=()=>{const v=$("customTalent").value.trim();if(!v)return;data.customTalents.push(v);$("customTalent").value="";save()};
$("masterBtn").onclick=()=>$("masterPanel").classList.add("open"); /* sem senha: a permissão vem do papel na nuvem (Etapa 4) */$("closeMaster").onclick=()=>$("masterPanel").classList.remove("open");$("addVoc").onclick=addVoc;$("addTrack").onclick=addTrack;$("editSelectedVoc").onclick=()=>editSelected("voc");$("editSelectedTrack").onclick=()=>editSelected("track");$("resetContent").onclick=()=>{if(confirm("Restaurar vocações e trilhas originais? Isso remove as alterações do mestre.")){vocations=clone(ORIGINAL_VOCATIONS);tracks=clone(ORIGINAL_TRACKS);save()}};
$("exportBtn").onclick=()=>{const blob=new Blob([JSON.stringify({data,vocations,tracks},null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="tulpa-rpg-ficha.json";a.click();URL.revokeObjectURL(url)};$("importBtn").onclick=()=>$("importFile").click();$("importFile").onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const x=JSON.parse(await f.text());if(x.data)data={...blank(),...x.data};if(x.vocations)vocations=x.vocations;if(x.tracks)tracks=x.tracks;save();toast("Ficha importada.")}catch(err){toast("Arquivo JSON inválido.")}};
